SELECT b.content_hash,bd.dir_id,bd.file_name,bd.local_hash FROM book_dir bd JOIN book b ON b.row_id=bd.book_row_id JOIN dir_paths dp ON dp.id=bd.dir_id WHERE b.deleted_at IS NULL AND bd.deleted_at IS NULL AND bd.dir_id IN (WITH RECURSIVE subtree(id) AS (SELECT id FROM dir WHERE id=?1 AND deleted_at IS NULL UNION ALL SELECT d.id FROM dir d JOIN subtree s ON d.parent_id=s.id WHERE d.id!=d.parent_id AND d.deleted_at IS NULL) SELECT id FROM subtree)
